package main

const indexHTML = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DevOps Task Board</title><style>body{font:16px system-ui;max-width:700px;margin:5rem auto;padding:0 1rem;color:#172554}h1{font-size:2rem}input,button{font:inherit;padding:.6rem}input{max-width:100%}button{background:#1d4ed8;color:white;border:0;cursor:pointer}li{padding:.5rem;border-bottom:1px solid #ddd}small{color:#64748b}</style><h1>DevOps Task Board</h1><p id="greeting"></p><p><input id="token" type="password" placeholder="API token" autocomplete="off"> <input id="title" maxlength="120" placeholder="New task"> <button id="add">Add</button></p><p id="status" role="status"></p><ul id="tasks"></ul><small>Token stays in this browser tab. GET /metrics exposes Prometheus metrics.</small><script>async function load(){const r=await fetch('/api/tasks');const data=await r.json();document.querySelector('#greeting').textContent=data.greeting;const list=document.querySelector('#tasks');list.replaceChildren();for(const task of data.tasks){const li=document.createElement('li');li.textContent=task.title;list.append(li)}}document.querySelector('#add').onclick=async()=>{const title=document.querySelector('#title').value;const token=document.querySelector('#token').value;const r=await fetch('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({title})});document.querySelector('#status').textContent=r.ok?'Task saved':await r.text();if(r.ok){document.querySelector('#title').value='';load()}};load();</script></html>`
